def search_in_matrix(matrix, target):
    top = 0
    bot = len(matrix) - 1

    while top <= bot:
        mid = (top + bot) // 2

        if matrix[mid][0] < target and matrix[mid][-1] > target:
            break
        elif matrix[mid][0] > target:
            bot = mid - 1
        else:
            top = mid + 1

    row = (top + bot) // 2

    left = 0
    right = len(matrix[row]) - 1

